const identifyTaskDB=[{"s":"Un sitio donde tu gente ya está y donde apareces cada cierto tiempo.","type":"Un canal"},{"s":"Abrir uno nuevo con el anterior sin contestar.","type":"La señal de alarma"},{"s":"Sirve para que te conozca gente nueva.","type":"Canal que alcanza"},{"s":"Sirve para seguir hablando con quien ya te conoce.","type":"Canal que retiene"},{"s":"La lista de correos y el papel impreso.","type":"Canal propio"},{"s":"Una cuenta que puede apagar alguien que no eres tú.","type":"Canal prestado"},{"s":"Trae gente mientras se paga y se apaga al dejar de pagar.","type":"Canal alquilado"},{"s":"El sitio concreto al que lleva cada publicación.","type":"La puerta"},{"s":"Lo que aguantas publicar la semana peor del año.","type":"El ritmo real"},{"s":"Publicar algo que sirve aunque no te contraten.","type":"Enseñar"}];
const classifyTaskDB=[{"w":"La lista de sesenta correos","gen":"Tipo de canal","n":"No te lo quitan","g":"Propio","t":"Vale más que cuatro mil seguidores"},{"w":"La página en una red social","gen":"Tipo de canal","n":"Lo apaga otro","g":"Prestado","t":"Sirve para traer gente a lo propio"},{"w":"La charla en un centro nuevo","gen":"Para qué sirve","n":"Gente nueva","g":"Alcanza","t":"Sin puerta no sirve de nada"},{"w":"El grupo de las veintitrés maestras","gen":"Para qué sirve","n":"Gente que vuelve","g":"Retiene","t":"Es el que sostiene el proyecto"},{"w":"Cuántas piden una ficha","gen":"Qué se mira","n":"Se decide con ella","g":"Medida que sirve","t":"Se apunta cada mes"},{"w":"El número de seguidores","gen":"Qué se mira","n":"Sube solo","g":"Número vacío","t":"No se puede llevar a ninguna parte"},{"w":"Una idea para el lunes","gen":"Qué se publica","n":"La mayoría","g":"Enseñar","t":"Sirve aunque no te contraten"},{"w":"El precio del material del año","gen":"Qué se publica","n":"Poco y sin rodeos","g":"Pedir","t":"Quien rodea parece que esconde"},{"w":"Publicar los lunes, aunque sea corto","gen":"Ritmo","n":"Aguanta todo el año","g":"Ritmo real","t":"Es el de la semana peor"},{"w":"Publicar cada día en enero","gen":"Ritmo","n":"Se apaga en marzo","g":"Ritmo de las ganas","t":"Deja el canal muerto"}];
const completeTaskDB=[{"s":"El canal está donde ya está tu ___.","opts":["gente","competencia","oficina"],"ans":"gente"},{"s":"Un canal que no se sostiene doce meses es una ___.","opts":["campana","prueba","red"],"ans":"campana"},{"s":"El ritmo se decide con la semana ___ del año.","opts":["peor","mejor","primera"],"ans":"peor"},{"s":"Sin ___ hay aplausos y ningún contacto.","opts":["puerta","anuncio","foto"],"ans":"puerta"},{"s":"Lo ___ es lo que no te pueden quitar.","opts":["propio","prestado","pagado"],"ans":"propio"},{"s":"Lo prestado sirve para traer gente a lo ___.","opts":["propio","pagado","nuevo"],"ans":"propio"},{"s":"Primero se construye el canal que ___.","opts":["retiene","alcanza","cuesta"],"ans":"retiene"},{"s":"De lo que se publica, la mayor parte es ___.","opts":["ensenar","pedir","mostrar"],"ans":"ensenar"}];
const explainQuestions=[{"q":"Explica qué es un canal y por qué una cuenta abierta no lo es.","ans":"Un canal es un sitio donde tu gente ya está y donde tú apareces cada cierto tiempo con algo que le sirve. Las tres partes importan: que la gente esté (si no está, no es un canal, es un escaparate en una calle vacía), que aparezcas cada cierto tiempo (si es cuando hay ganas, no hay canal) y que lo que lleves sirva. Una cuenta abierta y muda no cumple ninguna de las tres, y además hace daño: dice sin decirlo que el proyecto empieza cosas y no las termina, que es justo lo contrario de lo que se quiere transmitir. Por eso la regla corta de la etapa es que un canal que no puedes sostener doce meses no es un canal, es una campaña. Una campaña está bien, siempre que se sepa desde el principio que va a terminar."},{"q":"¿Cuál es la señal de alarma de esta etapa y qué está pasando cuando aparece?","ans":"Abrir un canal nuevo cuando el anterior está sin contestar. Lo que está pasando es que se confunde avanzar con moverse: abrir una cuenta se siente como progreso porque es visible y rápido, mientras que contestar tres preguntas pendientes en el grupo no se ve desde fuera. Pero el esfuerzo disponible es el mismo, así que abrir otro canal no suma, reparte: lo que había para uno ahora se divide entre dos y los dos quedan a medias. Casi nunca falta un canal; casi siempre falta ritmo en el que ya se tiene. La comprobación es simple y molesta: antes de abrir nada, mirar si hay algo sin contestar en lo que ya existe. Si lo hay, ese es el trabajo, y no se parece nada a abrir un canal nuevo."},{"q":"Explica la diferencia entre el canal que alcanza y el que retiene, y cuál se construye primero.","ans":"El que alcanza sirve para que te conozca gente nueva: una charla en un centro, un video que alguien comparte, un anuncio pagado. Se mide en personas que llegan por primera vez. El que retiene sirve para seguir hablando con quien ya te conoce: el grupo de maestras, el correo mensual, la hoja que se entrega en la reunión. Se mide en gente que vuelve. Primero se construye el que retiene, aunque tenga doce personas, porque el error clásico es gastarlo todo en alcanzar sin tener dónde guardar a los que llegan: la gente mira, se va, y al mes siguiente hay que volver a buscarla, que es el trabajo más caro que existe. Con un canal que retiene, cada persona que llega se queda, y entonces sí vale la pena gastar en alcanzar."},{"q":"¿Qué son los canales propios, prestados y alquilados, y cuál es la regla que los ordena?","ans":"Propio es lo que no te pueden quitar: la lista de correos, el número de WhatsApp, el papel impreso, la aplicación de la casa. Prestado es una cuenta en una plataforma: funciona, es gratis y la puede apagar alguien que no eres tú, sin avisar y sin devolverte los contactos. Alquilado es el que se paga por aparecer, y trae gente mientras se paga: es un grifo, no una casa. La regla que los ordena es que lo prestado y lo alquilado sirven para traer gente a lo propio, nunca al revés. Todo lo que se publica en una plataforma tiene que terminar en algo tuyo, aunque sea un número de teléfono apuntado a mano. Por eso una lista de sesenta correos vale más que cuatro mil seguidores prestados, aunque nadie presuma nunca de sesenta correos."},{"q":"Explica qué es la puerta y qué pasa cuando falta.","ans":"La puerta es el sitio concreto al que lleva cada publicación: un enlace, un código impreso, un número al que escribir, una lista donde apuntarse. Cuando falta, la mejor publicación del año consigue admiración y ni un solo contacto, y admiración no es lo que se estaba buscando. El caso más claro es la charla: cuarenta minutos delante de veinte maestras que no te conocen es el mejor canal de alcance que existe, y también el que más se desperdicia, porque se sale de ahí con aplausos y sin nada. La puerta se prepara antes de entrar, no se improvisa al final: hojas impresas con el código y una lista para apuntar el correo de quien quiera el mensual. Y da una medida clarísima: si de una charla salieron cero correos, el problema no fue la charla, fue que no había puerta."},{"q":"Di cómo se elige el ritmo de un canal y qué se mira a los tres meses.","ans":"El ritmo se elige con la semana peor del año, no con la mejor: lo que se puede hacer con clases, exámenes y la casa encima. Si un ritmo solo funciona en vacaciones, el ritmo real es otro, y conviene decirlo antes que descubrirlo en marzo con el canal ya apagado. Publicar cada día en enero y no volver a publicar desde marzo deja peor imagen que haber publicado una vez al mes todo el año. A los tres meses se mira una medida que sirva para decidir algo: cuántas personas contestan, cuántas piden una ficha, cuántos correos nuevos salieron de una charla, cuántas vuelven al mes siguiente. No sirven los seguidores ni los «me gusta», porque suben solos y no se pueden llevar a ninguna parte. Y la medida se escribe antes, con número, junto con qué se haría si sale por debajo."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

