function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"El grupo de WhatsApp de las maestras existe solo, tiene veintitrés personas y ahí se preguntan cosas todas las semanas. Nadie lo abrió como canal."},{"txt":"Una hoja de la ficha con el código impreso, entregada en mano en la reunión de padres. No depende de internet ni de ninguna plataforma."},{"txt":"Una página heredada en una red social: dos años, cuatrocientos seguidores y la última publicación es de marzo del año pasado."},{"txt":"Una lista de sesenta correos recogidos en los talleres. Ninguno se ha usado todavía y siguen guardados en una hoja de cálculo."},{"txt":"Un colega aconseja abrir un canal de videos. Un video corto y decente son dos horas entre grabar, cortar y subir."},{"txt":"Cuarenta minutos de charla delante de veinte maestras que no te conocen, invitado por la directora de un centro nuevo."},{"txt":"Doscientos lempiras para que una publicación la vean mil personas del municipio, y se pueden repetir cada mes."},{"txt":"Un grupo de doscientos maestros que hablan de metodología y donde da gusto publicar, porque entienden lo que uno hace."}];
const critCaseQuestions=["1. ¿Está ahí tu gente? Nombra a tres personas reales o di que no.","2. ¿Qué ritmo aguantarías la semana peor del año?","3. ¿Cuál es la puerta, escrita como una frase concreta?","4. Escribe en 3-4 frases qué mirarías a los tres meses y qué harías si sale por debajo."];
const critCaseGuides=["Se piden nombres, no categorías. «Maestras» no vale; «la profe Marta de la Escuela Ramón Rosa» sí. Si no salen tres nombres, la gente todavía no está ahí.","El ritmo de la semana peor, con clases y exámenes encima. Suele ser la mitad de lo que uno cree, y decirlo ahora ahorra un canal apagado en marzo.","La puerta es un sitio concreto: un código impreso, una lista donde apuntarse, un número al que escribir. «Que nos conozcan» no es una puerta.","Una medida que sirva para decidir: cuántas contestan, cuántas piden una ficha, cuántos correos nuevos. Y escrita antes, con número, junto con qué se hace si sale por debajo."];

const critErrorBank=[{"txt":"\"Voy a abrir el canal de videos y así estamos en todas partes\".","g1":"Estar en todas partes con el mismo esfuerzo significa estar a medias en todas. Y la señal de alarma está ahí mismo: hay tres preguntas sin contestar en el grupo que ya funciona.","g2":"La cuenta lo decide: dos horas por video, uno por semana, son ocho horas al mes de un maestro que da clases de doce y media a cinco y media."},{"txt":"\"Tenemos cuatrocientos seguidores, eso ya es una base\".","g1":"Cuatrocientos seguidores en una cuenta prestada no son cuatrocientas personas esperando: son un número que no se puede llevar a ninguna parte si mañana cierra la plataforma.","g2":"La base son los sesenta correos que sí se pueden guardar, aunque el número parezca ridículo al lado del otro."},{"txt":"\"La charla salió muy bien, la gente aplaudió mucho\".","g1":"Los aplausos no son una medida. La pregunta es cuántos correos nuevos salieron de ahí, y si son cero, la charla no sirvió para nada aunque fuera buena.","g2":"La puerta se prepara antes de entrar: hojas impresas con el código y una lista para apuntar el correo. Improvisarla al final no funciona."},{"txt":"\"Publico todos los días, así el algoritmo me ayuda\".","g1":"Todos los días es el ritmo de las ganas del primer mes. En marzo, con exámenes, se para, y un canal que se para deja peor imagen que uno que publicaba una vez al mes.","g2":"El ritmo se elige con la semana peor del año y se cumple. Una vez por semana, cumplido doce meses, vale más que treinta publicaciones en enero."},{"txt":"\"En el grupo de colegas es donde más me responden, ahí voy a publicar\".","g1":"Ahí responden porque entienden el trabajo, y eso se agradece, pero los colegas no van a contratar nada: hacen lo mismo que tú.","g2":"Ese grupo sirve para aprender y para que te inviten a dar charlas, que es otra cosa muy útil. Pero la maestra que necesita la ficha no está ahí."},{"txt":"\"Los anuncios funcionaron, así que ya tenemos canal\".","g1":"Lo pagado trae gente mientras se paga y se apaga el día que se deja de pagar. Es un grifo, no una casa.","g2":"Sirve para empujar algo concreto que ya funciona y solo si hay algo propio al otro lado, con un número escrito antes de pagar: cuántos contactos harían que valiera la pena."}];

const critDecisionBank=["El grupo de maestras funciona solo y tiene tres preguntas sin contestar: ¿se abre un canal nuevo o se atiende ese?","Una página heredada con cuatrocientos seguidores lleva un año sin publicar: ¿se cierra, se sostiene o se deja así?","Sesenta correos recogidos en talleres y sin usar: ¿se empieza a escribir y con qué ritmo?","Un colega insiste en el canal de videos: ¿se abre, se aplaza por escrito o se prueba un mes?","Hay charla en un centro nuevo el jueves: ¿qué se prepara antes de entrar?","Doscientos lempiras para una publicación pagada: ¿se pagan y con qué escrito antes?","El grupo de colegas es donde más responden: ¿se publica ahí lo mismo que en el de maestras?","La hoja impresa cuesta dinero de fotocopia cada mes: ¿se mantiene, se reduce o se sustituye por algo digital?"];
const critDecisionGuide="La decisión correcta sigue las reglas de la casa: el canal se elige por dónde ya está la gente y no por dónde se está cómodo, así que lo primero es nombrar a tres personas reales que estén ahí. El ritmo se decide con la semana peor del año, porque un canal que no se sostiene doce meses no es un canal, es una campaña. Antes de abrir uno nuevo se mira si queda algo sin contestar en el que ya funciona, que es la señal de alarma de esta etapa. Primero se construye el canal que retiene y después el que alcanza; lo prestado y lo pagado sirven para traer gente a lo propio, nunca al revés. Toda publicación termina en una puerta concreta, y a los tres meses se mira un número que sirva para decidir algo, escrito antes.";

const critCompareBank=[{"a":"Sostener el grupo de veintitrés maestras con una cosa útil por semana.","b":"Abrir un canal de videos con un video semanal.","ga":"Caso A: la gente ya está, el ritmo cabe en la semana peor y cada publicación puede llevar a una ficha. Se puede sostener doce meses.","gb":"Caso B: son ocho horas al mes que no existen, y en marzo se apaga. Un canal apagado dice que el proyecto empieza cosas y no las termina."},{"a":"Empezar el correo mensual con sesenta direcciones propias.","b":"Empujar la página prestada hasta llegar a mil seguidores.","ga":"Caso A: sesenta correos son sesenta personas a las que puedes llegar mañana pase lo que pase, porque la lista está en tu computadora.","gb":"Caso B: mil seguidores prestados desaparecen el día que la plataforma cambie las reglas, y no hay manera de avisarles."},{"a":"Llevar a la charla hojas impresas con código y una lista de correos.","b":"Dar la charla y decir el nombre del proyecto al final.","ga":"Caso A: hay puerta, así que se puede contar cuántos entraron por ella y decidir si volver a ese centro.","gb":"Caso B: hay aplausos y ningún contacto, y a los tres meses no se sabe si la charla sirvió de algo."},{"a":"Cerrar bien la página muerta con una última publicación fijada.","b":"Dejarla como está por si algún día se retoma.","ga":"Caso A: cuesta diez minutos, redirige a quien llegue y deja de dar la impresión de proyecto abandonado.","gb":"Caso B: sigue siendo lo primero que encuentra quien busca el proyecto, y lo que encuentra es una publicación de hace un año."}];

const critCauseBank=[{"cause":"Se abre un canal nuevo con el anterior sin contestar.","guide":"El mismo esfuerzo se reparte entre más sitios y los dos quedan a medias. Y el canal que ya tenía gente esperando es el que más se resiente, porque ahí sí notan la ausencia."},{"cause":"Se elige el ritmo con las ganas del primer mes.","guide":"En marzo, con exámenes, se para. Un canal que publicaba a diario y se detiene deja peor imagen que uno que publicaba una vez al mes y sigue."},{"cause":"Se publica sin puerta.","guide":"Se consiguen aplausos y ningún contacto, y a los tres meses no hay manera de saber si eso sirvió para algo. La puerta es lo que convierte una publicación en una decisión de otra persona."},{"cause":"Todo el proyecto vive en canales prestados.","guide":"El día que la plataforma cambie las reglas o cierre la cuenta, no queda forma de avisar a nadie. Los contactos eran de la plataforma, no del proyecto."},{"cause":"Se mide con seguidores y con «me gusta».","guide":"Son números que suben solos y no se pueden llevar a ninguna parte. Con ellos no se puede decidir si un canal sigue o se cierra, que es para lo que sirve medir."},{"cause":"Se publica sobre todo en el grupo donde están los colegas.","guide":"Es el canal cómodo: ahí se aprecia el trabajo y eso anima, pero quien necesita el material no está ahí. Se confunde reconocimiento con alcance."}];
const critEffectBank=[{"effect":"Un canal se sostuvo doce meses seguidos.","guide":"Se eligió el ritmo con la semana peor del año, no con las ganas de enero, y se cumplió aunque algunas semanas la publicación fuera corta."},{"effect":"De una charla salieron once correos nuevos.","guide":"Había puerta preparada antes de entrar: hojas impresas con el código y una lista para apuntarse. Sin eso habrían salido cero."},{"effect":"El proyecto sobrevivió al cierre de una cuenta.","guide":"Los contactos estaban en algo propio: una lista de correos y una libreta con teléfonos. Lo prestado había servido solo para traer gente hasta ahí."},{"effect":"Se supo exactamente cuánto cuesta conseguir un contacto.","guide":"Antes de pagar el anuncio se escribió cuántos contactos harían que valiera la pena. Al final se contaron y se comparó con lo escrito."},{"effect":"Una página abandonada dejó de hacer daño.","guide":"Se cerró bien: una última publicación diciendo dónde encontrar el proyecto ahora, dejada fijada arriba. Diez minutos de trabajo."},{"effect":"El grupo de maestras empezó a pedir fichas solo.","guide":"Se publicó cosa útil cada semana durante meses, con la puerta siempre puesta, y sin pedir nada más que de vez en cuando."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El canal que se sostiene · Forma ${cf} · Canales · Ruta de la Marca`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El canal sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Está ahí tu gente, qué ritmo aguantarías la semana peor del año y a dónde lleva cada publicación? Explica por qué ese canal se sostiene mejor que abrir uno nuevo o que publicar donde estás cómodo.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos se puede sostener doce meses? 2. ¿Por qué el otro se apaga y qué deja detrás cuando se apaga?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El canal que se sostiene: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El canal sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Está ahí tu gente, qué ritmo aguantarías la semana peor del año y a dónde lleva cada publicación? Explica por qué ese canal se sostiene mejor que abrir uno nuevo o que publicar donde estás cómodo.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos se puede sostener doce meses? 2. ¿Por qué el otro se apaga y qué deja detrás cuando se apaga?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El canal que se sostiene · Canales · Ruta de la Marca · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El canal que se sostiene · Canales · Ruta de la Marca · Etapa 4 · Marketing y Marca</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El canal que se sostiene · Canales · Ruta de la Marca · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

